from fastapi import FastAPI, Header, HTTPException
from pydantic import BaseModel, Field
from task_service import TaskService

app = FastAPI()
service = TaskService()

class TaskInput(BaseModel):
    question: str = Field(min_length=1, max_length=1000)

@app.post("/tasks", status_code=202)
def create_task(body: TaskInput, idempotency_key: str = Header(min_length=1)):
    try:
        return {"task_id": service.create(idempotency_key, body.question)}
    except ValueError as exc:
        raise HTTPException(status_code=409, detail=str(exc)) from exc

@app.get("/tasks/{task_id}")
def get_task(task_id: str):
    if task_id not in service.tasks:
        raise HTTPException(status_code=404, detail="task unavailable")
    return service.tasks[task_id]

@app.post("/tasks/{task_id}/cancel")
def cancel_task(task_id: str):
    get_task(task_id)
    service.cancel(task_id)
    return get_task(task_id)
